      empireFoodStates.set(0, freshEmpireFoodState());
      for (const ai of aiStartHexes) {
        if (!empireFoodStates.has(ai.ownerId)) {
          empireFoodStates.set(ai.ownerId, freshEmpireFoodState());
        }
      }
      bindEmpireFoodRuntime(empireFoodStates);
