    /** Miasto w trybie ręcznej okolicy na mapie 3D (po „Mapa” w panelu). */
    let okolicaMapEditCityId: string | null = null;
    let okolicaOverlayGroup: THREE.Group | null = null;
    /** Izolacja widoku 3D przy panelu miasta — tylko okolica, bez mapy strategicznej. */
    let cityPanelViewSaved: { x: number; z: number; dist: number } | null = null;
    let cityPanelViewCityId: string | null = null;

    function okolicaHexKeysForCity(city: City, pad = 1): Set<string> {
      const keys = new Set<string>();
      const rad = cityRangeForPopulation(city.population) + pad;
      for (const key of Object.keys(map.hexes)) {
        const hex = map.hexes[key];
        if (!hex) continue;
        const d = hexDistance(city.q, city.r, hex.coords.q, hex.coords.r);
        if (d <= rad) keys.add(key);
      }
      return keys;
    }

    function applyCityPanelWorldView(active: boolean, city?: City): void {
      if (active && city) {
        if (cityPanelViewSaved === null) {
          cityPanelViewSaved = camCtrl.getFocusState();
        }
        cityPanelViewCityId = city.id;
        const { x, z } = axialToWorld(city.q, city.r, HEX_R);
        const rad = cityRangeForPopulation(city.population);
        const dist = Math.max(14, Math.min(42, 10 + rad * 3.8));
        camCtrl.focusAt(x, z, dist);
      } else {
        if (cityPanelViewSaved !== null) {
          const saved = cityPanelViewSaved;
          camCtrl.focusAt(saved.x, saved.z, saved.dist);
          cityPanelViewSaved = null;
        }
        cityPanelViewCityId = null;
        restoreTerritoryBorderAfterCityPanel();
      }
      // D3: usunięty zbędny refreshFog() przy otwarciu panelu miasta — mgła się tu nie zmienia
      // (widoczność miast ustawia cityRenderer.sync; poprawność mgły dają realne zdarzenia: ruch/tura).
      cityRenderer.sync(cities, _cityRenderOpts());
      refreshRangeOverlays();
      refreshTerritoryBorderOverlay();
      refreshWorkerFieldOverlay();
      refreshTradeRoutesOverlay();
    }

    function okolicaHexWorkable(q: number, r: number): boolean {
      // P-HEKS-ISWORKABLE-OVERLAY-VS-SILNIK-HIPOTEZA: deleguje do wspolnego zrodla
      // prawdy (`isLandWorkableHex` w okolica.ts), uzywanego rowniez przez silnik
      // ekonomii i wszystkie sciezki zapisu trybu recznego -- overlay/silnik/UI
      // musza zgadzac sie co do tego, ktore pole nadaje sie do obsadzenia.
      return isLandWorkableHex(map, q, r);
    }

    function okolicaWorkedKeySet(city: City): Set<string> {
      const nodes = buildAllTerritoryNodes();
      const worked = resolveWorkedTiles(city, map, (q, rr) => yieldOfMapHex(map, q, rr), {
        isWorkable: okolicaHexWorkable,
        territoryNodes: nodes,
        ownerId: city.ownerId,
      });
      return new Set(worked.map(t => t.key));
    }

    function disposeOkolicaOverlay(): void {
      if (!okolicaOverlayGroup) return;
      try { scene.remove(okolicaOverlayGroup); } catch { /* scena może być już disposed */ }
      disposeCityOkolicaOverlayGroup(okolicaOverlayGroup);
      okolicaOverlayGroup = null;
    }

    function syncOkolicaOverlay(): void {
      if (!isCityPanelOpen()) {
        disposeOkolicaOverlay();
        return;
      }
      const cityId = getOpenCityPanelCityId();
      const city = cityId ? cities.find(c => c.id === cityId) : undefined;
      if (!city || city.ownerId !== 0) {
        disposeOkolicaOverlay();
        return;
      }
      okolicaOverlayGroup = syncCityOkolicaOverlay(scene, okolicaOverlayGroup, map, {
        cityQ: city.q,
        cityR: city.r,
        range: cityRangeForPopulation(city.population),
        workedKeys: okolicaWorkedKeySet(city),
        yieldOf: (q, rr) => yieldOfMapHex(map, q, rr),
        showYields: true,
        // P-CHLOPEK-DWA-SYSTEMY-KOLOR-NIESPOJNE: odznaka 👤 w okolicy bierze kolor z tej samej
        // palety co ikona 👤 na mapie świata — właściciel z miasta, nie sztywne 0.
        ownerId: city.ownerId,
      });
    }

    function hideCityPanelFull(): void {
      hideCityUnitPick();
      hideCityForeignPick();
      hideUnitForeignPick();
      if (closeCityPanelIfOpen()) {
        requestAnimationFrame(() => tryOpenNextFirstContactCard());
        return;
      }
      hideCityPanel();
      applyCityPanelWorldView(false);
      disposeOkolicaOverlay();
      refreshWorkerFieldOverlay();
      updateHud();
      requestAnimationFrame(() => tryOpenNextFirstContactCard());
    }

    function applyOkolicaTileAdjust(cityId: string, q: number, r: number, _delta: number): void {
      const city = cities.find(c => c.id === cityId);
      if (!city || city.ownerId !== 0) return;
      const res = toggleTileWorker(city, map, q, r, undefined, buildAllTerritoryNodes());
      if (res.ok) {
        city.okolicaReczne = res.reczne;
        city.okolicaTryb = 'reczny';
        markCityStateDirty(); // D10: zmiana pól roboczych → przelicz
        // P-AUTO-WYZYWIENIE-BUG1: przydział 👤 zmienił produkcję żywności TEGO miasta
        // NA ŻYWO (nie na koniec tury) -- przelicz i, jeśli trzeba, obniż poziom racji od razu.
        applyLiveSafeRationForCity(cityId);
        updateHud();
        refreshCityPanelIfOpen();
        syncOkolicaOverlay();
        refreshWorkerFieldOverlay();
      } else {
        const msg: Record<string, string> = {
          limit_populacji: 'Brak wolnych obywateli — najpierw zabierz 👤 z innego pola.',
          poza_zasiegiem: 'To pole jest poza zasięgiem okolicy.',
          obce_terytorium: 'Tylko w swoim terytorium — ten heks należy do innego państwa.',
          centrum_miasta: 'Centrum miasta nie przyjmuje 👤 — wybierz pole obok.',
          brak_ludnosci: 'Miasto nie ma ludności do pracy w polu.',
          brak_robotnika: 'Na tym polu nie ma przypisanego 👤.',
        };
        showHintMessage(msg[res.reason ?? ''] ?? 'Nie można zmienić przypisania pola.', 2800);
      }
    }

    /** Lewy klik na mapie: toggle 👤 (przypisz / zabierz). */
    function toggleOkolicaTileOnMap(cityId: string, q: number, r: number): void {
      applyOkolicaTileAdjust(cityId, q, r, 0);
    }

    function enterOkolicaMapMode(cityId: string): void {
      okolicaMapEditCityId = cityId;
      const city = cities.find(c => c.id === cityId);
      showHintMessage(
        (city?.name ?? 'Miasto') +
        ' — kliknij heks w okolicy, aby przypisać 👤 (panel pozostaje otwarty).',
        5000,
      );
    }

    function exitOkolicaMapMode(): void {
      if (okolicaMapEditCityId === null) return;
      okolicaMapEditCityId = null;
    }

    function isWorldMapUnitMode(): boolean {
      if (isCityPanelOpen()) return false;
      if (isPreBattleOpen()) return false;
      if (isPostBattleSummaryOpen()) return false;
      if (isArmyMergePanelOpen()) return false;
      if (isArmyMergePickPanelOpen()) return false;
      if (isArmySplitPanelOpen()) return false;
      if (isSiegeMapPanelOpen()) return false;
      if (isCityUnitPickOpen()) return false;
      return true;
    }

    function hudHtmlEsc(raw: string): string {
      return raw.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

    /** Rozszerzona karta jednostki w panelu bocznym (Maciej 2026-07-28). */
    let unitSideDetailExpanded = false;

    /**
     * Decyzja 81=A (2026-07-25): etykieta Danina/Podatek DLA TEGO KONKRETNEGO
     * HEKSU -- wg WLASCICIELA TERYTORIUM (territoryOwnerAtLive), nie gracza
     * patrzacego. Ten sam wzorzec liczenia jak buildEmpireTradeSnap (ok. linii
     * 7719): stolica ownera (capitalCityIdForOwner) + jego odkryte technologie
     * (unlockedTechsForOwner) + jego AKTUALNY dostep do zlota
     * (ownerHasZlotoAccessNow) -- jedna sciezka liczenia bramki, zeby panel
     * miasta i tooltip heksu nigdy nie rozjechaly sie w odpowiedzi na to samo
     * pytanie (dokladnie ten rozjazd juz raz naprawialismy przy mnozniku
     * cywilizacyjnym).
     * Heks NICZYJ (poza terytorium kazdej cywilizacji) -> brak wlasciciela,
     * bramka nie ma czego sprawdzic -> zawsze "Danina" (jawnie, nie tylko
     * przez fallback domyslny w tooltipie).
     * Reszta tooltipa (rozbicie plonow) juz dzis pokazuje pelne dane dla
     * DOWOLNEGO heksu, w tym obcego/wrogiego, bez ukrywania -- wiec etykieta
     * rowniez pokazuje realny stan WLASCICIELA heksu (parytet z reszta panelu,
     * nie stan gracza patrzacego).
     */
    function hexDaninaLabelAt(_q: number, _r: number): 'Podatek' {
      return 'Podatek';
    }

    /** D17=A: panel kontekstowy — pole mapy + opcjonalnie jednostka na tym heksie. */
    function buildHexContextPanelMessage(): string | null {
      if (!isWorldMapUnitMode() || hexDetailHex === null) return null;
      const hex = map.hexes[keyOf(hexDetailHex.q, hexDetailHex.r)];
      if (!hex) return null;
      const cityOn = cities.find(c => c.q === hexDetailHex!.q && c.r === hexDetailHex!.r);
      const hexKey = keyOf(hexDetailHex.q, hexDetailHex.r);
      let hexWorkedForMagazyn = cityOn != null;
      if (!hexWorkedForMagazyn) {
        const workedMap = collectWorkedHexOwnerMap(cities, map, {
          isWorkable: okolicaHexWorkable,
          territoryNodes: buildAllTerritoryNodes(),
        });
        hexWorkedForMagazyn = workedMap.has(hexKey);
      }
      return buildHexContextTooltipHtml({
        q: hexDetailHex.q,
        r: hexDetailHex.r,
        hex,
        hexWorkedForMagazyn,
        cityName: cityOn?.name ?? null,
        cityIsCityState: cityOn != null && cityOn.ownerId !== 0 && !!cityOn.startCityState,
        cityOwnerLabel: cityOn != null && cityOn.ownerId !== 0
          ? ownerDiploLabel(cityOn.ownerId)
          : null,
        cityPopulation: cityOn?.population ?? null,
        currentEra: player.era,
        playerCivType: String(player.civType || _menuCivId || ''),
        daninaLabel: hexDaninaLabelAt(hexDetailHex.q, hexDetailHex.r),
        esc: hudHtmlEsc,
      });
    }

    function playerFormalRelationLabel(ownerId: number): string {
      if (isBarbarian(ownerId)) return 'Wojna';
      let hasNap = false;
      let hasTrade = false;
      for (const d of activeDeals) {
        if (!d.strony.includes(0) || !d.strony.includes(ownerId)) continue;
        const k = normalizeTreatyKind(d.rodzaj);
        if (k === RodzajTraktatu.PaktNieagresji) hasNap = true;
        else if (k === RodzajTraktatu.UmowaSzlakow) hasTrade = true;
      }
      const rel = getDiploRelation(0, ownerId);
      return resolveFormalDiplomaticStatus({
        relationStatus: rel.status,
        allianceFormalKind: allianceFormalKindBetween(activeDeals, 0, ownerId),
        hasNap,
        hasTrade,
        contactEstablished: diplomaticContactEstablished.has(ownerId),
      }).label;
    }

    function unitOwnerMedallionHtml(ownerId: number): string {
      if (isBarbarian(ownerId)) {
        return `<span class="uc-owner-barb">${brandIconSvg('chip-death', 24)}</span>`;
      }
      return civLeaderMedallionHtmlById(
        civKeyForOwner(ownerId),
        civKolorHexFn(ownerId),
        empireEpochForOwner(ownerId),
        portraitForceCultureIcon(ownerId),
      );
    }

    /** Etykieta poziomu trudności do kart jednostek — kontekst dla liczb z econ-params. */
    function poziomTrudnosciLabelPl(): string {
      return _menuDifficulty === 'easy' ? 'łatwy'
        : _menuDifficulty === 'hard' ? 'trudny'
        : 'normalny';
    }

    /**
     * R-STATUS-PRZYCZYNA-CIERPIENIA-Q1=C: obie przyczyny cierpienia jednostki
     * (głód wojska + deficyt Złota) z REALNYMI wartościami parametrów dla
     * bieżącego poziomu trudności — te same, którymi liczy silnik.
     * Cywile (osadnik / robotnik / zwiadowca) nie tracą statów ani HP z żadnej
     * z tych przyczyn (patrz applyArmyStarvationHpLoss / applyGoldDeficitHpLoss),
     * więc karta też im tego nie pokazuje — parytet z ikonami na mapie.
     */
    function unitSufferingFields(u: RuntimeUnit) {
      const cywil = isCivilianUnit(u);
      const efParams = buildEmpireFoodParams(data.econParams, _menuDifficulty);
      const gdParams = buildGoldDeficitParams(data.econParams, _menuDifficulty);
      const glod = !cywil && isArmyHungry(u.ownerId);
      const zloto = !cywil && isGoldDeficit(u.ownerId);
      return {
        poziomTrudnosciLabel: poziomTrudnosciLabelPl(),
        glodWojska: glod,
        glodWojskaStatMult: efParams.glodWojskaStatMult,
        glodWojskaHpFrac: efParams.glodWojskaHpFrac,
        glodWojskaAtrycjaAktywna: glod && isArmyStarving(u.ownerId),
        glodWojskaTurDoAtrycji: glod
          ? getArmyStarvationCountdown(u.ownerId, efParams.glodWojskaKarencjaTur)
          : null,
        zlotoDeficyt: zloto,
        zlotoDeficytStatMult: gdParams.zlotoDeficytStatMult,
        zlotoDeficytHpFrac: gdParams.zlotoDeficytHpFrac,
        zlotoDeficytAtrycjaAktywna: zloto && isGoldDeficitStarving(u.ownerId),
        zlotoDeficytTurDoAtrycji: zloto
          ? getGoldDeficitCountdown(u.ownerId, gdParams.zlotoDeficytKarencjaTur)
          : null,
      };
    }

    function unitCardStatusFields(u: RuntimeUnit) {
      const vetEdu = veteranUnitEducationFields(u);
      const siegeCity = u.oblegaCityId
        ? cities.find(c => c.id === u.oblegaCityId)
        : null;
      return {
        ...unitSufferingFields(u),
        parametryPathPp: unitParametryBonusProc(u),
        pancerzPathPp: unitPancerzBonusProc(u),
        veteranBadgeLabel: vetEdu?.veteranBadgeLabel,
        veteranStarsTooltip: vetEdu?.veteranStarsTooltip,
        veteranExperienceLine: veteranExperienceLine(u),
        veteranPanelExplanation: vetEdu?.veteranPanelExplanation,
        inGarnizon: u.inGarnizon === true,
        sentry: u.sentry === true,
        autoExplore: u.autoExplore === true,
        ufortyfikowanyWPolu: u.ufortyfikowanyWPolu === true,
        oblegaCityName: siegeCity?.name,
        buildingBonusLabel: unitBuildingBonusLabel(u),
      };
    }

    function buildUnitContextTooltipForUnit(
      u: RuntimeUnit,
      opts: { readOnly?: boolean; ownerLabel?: string; relationLabel?: string } = {},
    ): string {
      const def = lookupUnitDef(u.typeId);
      const defName = String(def?.nazwa ?? def?.Nazwa ?? u.typeId);
      const status = unitCardStatusFields(u);
      const combat = unitCardCombatFor(u, def);
      const zasieg = normFieldVal(def['Zasi\u0119g'] ?? def['Zasieg'], 0);
      const expanded = unitSideDetailExpanded;
      const stackState = !opts.readOnly && u.ownerId === 0
        ? buildArmyStackHudStateInner()
        : null;
      const isArmy = stackState != null && stackState.unitCount > 1;
      return buildUnitContextTooltipHtml({
        displayName: isArmy ? `Armia · ${stackState.hexLabel}` : defName,
        headMeta: isArmy ? `${formatJednostkiCount(stackState.unitCount)} na heksie` : undefined,
        ownerEmblemHtml: unitOwnerMedallionHtml(u.ownerId),
        q: u.q,
        r: u.r,
        ruchLeft: u.ruchLeft,
        ruchMax: u.ruch,
        combat,
        hp: u.hp,
        category: u.category,
        zasieg,
        expanded,
        expandable: u.ownerId === 0 || opts.readOnly === true,
        stackCards: isArmy ? stackState.cards : undefined,
        actions: stackState?.actions,
        inGarnizon: status.inGarnizon,
        buildingBonusLabel: status.buildingBonusLabel,
        parametryPathPp: status.parametryPathPp,
        pancerzPathPp: status.pancerzPathPp,
        veteranProgress: u,
        veteranBadgeLabel: status.veteranBadgeLabel,
        veteranStarsTooltip: status.veteranStarsTooltip,
        veteranExperienceLine: status.veteranExperienceLine,
        veteranPanelExplanation: status.veteranPanelExplanation,
        sentry: status.sentry,
        ufortyfikowanyWPolu: status.ufortyfikowanyWPolu,
        oblegaCityName: status.oblegaCityName,
        // R-STATUS-PRZYCZYNA-CIERPIENIA-Q1=C: wiersze „głód wojska” / „deficyt Złota”.
        poziomTrudnosciLabel: status.poziomTrudnosciLabel,
        glodWojska: status.glodWojska,
        glodWojskaStatMult: status.glodWojskaStatMult,
        glodWojskaHpFrac: status.glodWojskaHpFrac,
        glodWojskaAtrycjaAktywna: status.glodWojskaAtrycjaAktywna,
        glodWojskaTurDoAtrycji: status.glodWojskaTurDoAtrycji,
        zlotoDeficyt: status.zlotoDeficyt,
        zlotoDeficytStatMult: status.zlotoDeficytStatMult,
        zlotoDeficytHpFrac: status.zlotoDeficytHpFrac,
        zlotoDeficytAtrycjaAktywna: status.zlotoDeficytAtrycjaAktywna,
        zlotoDeficytTurDoAtrycji: status.zlotoDeficytTurDoAtrycji,
        ownerLabel: opts.ownerLabel ?? ownerDiploLabel(u.ownerId),
        relationLabel: opts.relationLabel,
        readOnly: opts.readOnly,
        esc: hudHtmlEsc,
      });
    }

    function buildUnitContextPanelMessage(): string | null {
      if (!isWorldMapUnitMode()) return null;
      if (selectedId !== null) {
        const own = units.find(x => x.id === selectedId);
        if (own && own.ownerId === 0) {
          return buildUnitContextTooltipForUnit(own);
        }
      }
      if (foreignUnitInspectId !== null) {
        const foreign = units.find(x => x.id === foreignUnitInspectId);
        if (foreign && foreign.ownerId !== 0) {
          return buildUnitContextTooltipForUnit(foreign, {
            readOnly: true,
            ownerLabel: ownerDiploLabel(foreign.ownerId),
            relationLabel: playerFormalRelationLabel(foreign.ownerId),
          });
        }
      }
      return null;
    }

    function getContextPanelKind(): 'hex' | 'unit' | null {
      const unitMsg = buildUnitContextPanelMessage();
      const hexMsg = buildHexContextPanelMessage();
      if (unitMsg && !hexMsg) return 'unit';
      if (hexMsg && !unitMsg) return 'hex';
      if (hexMsg && unitMsg) {
        const inspectId = selectedId ?? foreignUnitInspectId;
        const u = inspectId !== null ? units.find(x => x.id === inspectId) : undefined;
        const sameHex = u && hexDetailHex && u.q === hexDetailHex.q && u.r === hexDetailHex.r;
        return sameHex ? 'hex' : (unitMsg ? 'unit' : 'hex');
      }
      return null;
    }

    function buildContextPanelData(): {
      kind: 'hex' | 'unit';
      html: string;
      ownUnit?: boolean;
      expandable?: boolean;
      expandInHtml?: boolean;
    } | null {
      const hexMsg = buildHexContextPanelMessage();
      const unitMsg = buildUnitContextPanelMessage();
      if (hexMsg && unitMsg) {
        const inspectId = selectedId ?? foreignUnitInspectId;
        const u = inspectId !== null ? units.find(x => x.id === inspectId) : undefined;
        const sameHex = u && hexDetailHex && u.q === hexDetailHex.q && u.r === hexDetailHex.r;
        if (sameHex) {
          return {
            kind: 'hex',
            html: hexMsg + '<div class="cp-sep"></div><div class="cp-unit-head">' + unitMsg + '</div>',
          };
        }
      }
      if (unitMsg) {
        const ownSelected = selectedId !== null && units.some(x => x.id === selectedId && x.ownerId === 0);
        return {
          kind: 'unit',
          html: unitMsg,
          ownUnit: ownSelected,
          expandable: ownSelected || foreignUnitInspectId !== null,
          expandInHtml: ownSelected || foreignUnitInspectId !== null,
        };
      }
      if (hexMsg) return { kind: 'hex', html: hexMsg };
      return null;
    }

    function buildContextPanelMessage(): string | null {
      return buildContextPanelData()?.html ?? null;
    }

    function clearForeignUnitInspect(): void {
      if (foreignUnitInspectId === null) return;
      foreignUnitInspectId = null;
      unitSideDetailExpanded = false;
      refreshD1bHud();
    }

    function inspectForeignUnit(u: RuntimeUnit): void {
      foreignUnitInspectId = u.id;
      lastBHex = { q: u.q, r: u.r };
      unitSideDetailExpanded = false;
      refreshD1bHud();
    }

    function clearPlayerUnitSelection(): void {
      if (selectedId !== null) clearPlannedMarch(selectedId);
      clearPlayerUnitSelectionStateOnly();
    }

    /** Odznacz jednostkę bez kasowania zaplanowanych marszów (koniec tury gracza). */
    function clearPlayerUnitSelectionStateOnly(): void {
      selectedId = null;
      unitSideDetailExpanded = false;
      reachable = new Set<string>();
      unitRenderer.clearHighlight();
      unitRenderer.clearPathRoute();
      unitRenderer.clearSelectionHex();
      hoverKey = null;
      setArmyListSelectedId(null);
      refreshD1bHud();
    }

    function focusCameraOnUnit(u: RuntimeUnit): void {
      const { x, z } = axialToWorld(u.q, u.r, HEX_R);
      const { dist } = camCtrl.getFocusState();
      camCtrl.focusAt(x, z, dist);
    }

    /** Po zakończeniu tury: odśwież pierścień, zasięg i kamerę dla wybranej jednostki. */
    function syncPlayerUnitSelectionOnMap(): void {
      if (selectedId === null) return;
      const u = units.find(x => x.id === selectedId);
      if (!u || u.ownerId !== 0) return;
      unitRenderer.setSelectionHex(u.q, u.r, u.ownerId);
      if (isSiegeMapPanelOpen()) {
        reachable = new Set<string>();
        unitRenderer.clearHighlight();
      } else if (stackCanMove(u) && !isAwaitingFirstPlayerCity()) {
        reachable = reachableWithMergeTargets(u);
        unitRenderer.setHighlight(reachable);
      } else {
        reachable = new Set<string>();
        unitRenderer.clearHighlight();
      }
      if (plannedMarches.has(u.id)) {
        refreshPlannedMarchPreview(u.id);
      }
      focusCameraOnUnit(u);
      refreshD1bHud();
    }

    /** Odznacz jednostkę na mapie świata (Escape / PPM). */
    function dismissPlayerUnitSelectionIfAny(): boolean {
      if (selectedId === null || !isWorldMapUnitMode()) return false;
      clearPlayerUnitSelection();
      refreshD1bHud();
      return true;
    }

    /** Zamknij listy z lewego toolbaru (powrót na czystą mapę). */
    function dismissToolbarSidePanels(): void {
      if (isArmyListHudOpen()) hideArmyListHud();
      if (isCityListHudOpen()) hideCityListHud();
      if (isDiploListHudOpen()) hideDiploListHud();
    }

    /** Listy toolbaru + tryby mapy (budowa, zasięgi kultury/religii, pickery) — czysta mapa / wejście w miasto.
     * Granice państw (territoryBorderVisible) NIE są tu gaszone — trwały wybór użytkownika aż do toggle OFF. */
    function dismissMapOverlayModes(): void {
      dismissToolbarSidePanels();
      if (buildModeOpen) exitBuildMode();
      if (cultureRangeVisible || religionRangeVisible) {
        cultureRangeVisible = false;
        religionRangeVisible = false;
        refreshRangeOverlays();
      }
      hideWondersPicker();
      hideEmpireOverlay();
      hideEmpireDetailPanel();
      hideCityUnitPick();
      hideCityForeignPick();
      hideUnitForeignPick();
    }

    function openCityPanelForPlayer(city: City): void {
      hideCityUnitPick();
      hideCityForeignPick();
      hideUnitForeignPick();
      hideScienceHubHud();
      hideWikiHubHud();
      hideSciencePicker();
      if (isDiplomacyAudienceOpen()) {
        hideDiplomacyAudience();
        diplomacyAudienceOwnerId = null;
      }
      if (isDiplomacyPanelOpen()) hideDiplomacyPanel();
      saveTerritoryBorderBeforeCityPanel();
      dismissMapOverlayModes();
      forceTerritoryBorderForCityPanel();
      exitOkolicaMapMode();
      clearPlayerUnitSelection();
      // P-CHLOPEK-DWA-SYSTEMY-KOLOR-NIESPOJNE: `applyCityPanelWorldView` woła w środku
      // `refreshWorkerFieldOverlay()` (i inne odświeżenia bramkowane `isCityPanelOpen()`),
      // więc MUSI iść PO `showCityPanel(...)`. Wołane wcześniej widziało panel jako jeszcze
      // zamknięty i odbudowywało warstwę 👤 mapy świata tuż przed otwarciem panelu. Warstwa
      // zostawała widoczna od otwarcia panelu do pierwszego z: przełączenie miasta
      // (`onSwitchCity`), ręczne przypisanie pola (`applyOkolicaTileAdjust`), koniec tury,
      // zamknięcie panelu — te ścieżki wołają `refreshWorkerFieldOverlay()` wprost i ją
      // czyściły. Zmiana trybu/priorytetu okolicy (`onOkolicaFocusChange`,
      // `onOkolicaEnterManual`, `onOkolicaRestoreAuto`) NIE czyściła jej — te wołają tylko
      // `syncOkolicaOverlay()`, który warstwy mapy świata w ogóle nie dotyka.
      showCityPanel(city, map, () => {
        hideCityPanel();
        applyCityPanelWorldView(false);
        disposeOkolicaOverlay();
        updateHud();
      });
      applyCityPanelWorldView(true, city);
      syncOkolicaOverlay();
      updateHud();
    }

    function selectPlayerUnit(unitId: string, keepListOpen = false, preserveDetailExpanded = false): void {
      const u = units.find(x => x.id === unitId);
      if (!u || u.ownerId !== 0) return;
      // R-SCOUT-ZWIEDZAJ-HIGHLIGHT 2026-08-04: NIE czyść autoExplore przy zaznaczeniu —
      // inaczej przycisk Zwiedzaj nigdy nie pokazuje stanu WŁ (złota ramka 3px).
      // Wyjście z auto: toggle Zwiedzaj / rozkaz marszu (planMarchTo) — jak Czuwaj.
      // Jednostka gracza ↔ lista/audiencja dyplomacji — wykluczają się (first contact + toolbar).
      ensureDiplomacyUiClosed();
      if (!preserveDetailExpanded) unitSideDetailExpanded = false;
      const stack = playerStackAt(u);
      if (stack.length > 1) syncStackRuchLeft(stack);
      if (isCityPanelOpen()) hideCityPanelFull();
      exitOkolicaMapMode();
      unitRenderer.clearPathRoute();
      hoverKey = null;
      foreignUnitInspectId = null;
      hexDetailHex = null;
      selectedId = u.id;
      lastBHex = { q: u.q, r: u.r };
      if (isSiegeMapPanelOpen()) {
        reachable = new Set<string>();
        unitRenderer.clearHighlight();
      } else {
        reachable = stackCanMove(u) && !isAwaitingFirstPlayerCity()
          ? reachableWithMergeTargets(u)
          : new Set<string>();
        unitRenderer.setHighlight(reachable);
      }
      unitRenderer.setSelectionHex(u.q, u.r, u.ownerId);
      setArmyListSelectedId(u.id);
      if (!keepListOpen) hideArmyListHud();
      if (plannedMarches.has(u.id)) {
        refreshPlannedMarchPreview(u.id);
      }
      refreshD1bHud();
    }

    /** Jednostka aktywna do cyklu Spacja/HUD — nie uśpiona, nie w garnizonie, nie ufortyfikowana w polu. */
    function isUnitActiveForCycle(u: RuntimeUnit): boolean {
      return u.sentry !== true
        && u.autoExplore !== true
        && u.inGarnizon !== true
        && u.ufortyfikowanyWPolu !== true;
    }

    /**
     * Wspólna implementacja list cyklowania armii gracza (1 wiodąca/heks; kolejność przestrzenna).
     * `requireMoves=true` → tylko stosy z dostępnym ruchem w tej turze (Spacja, auto-cykl „bęben”).
     * `requireMoves=false` → wszystkie aktywne stosy, niezależnie od ruchu (strzałki HUD ◀▶;
     * decyzja właściciela R-SPACJA-KOLEJNA-JEDNOSTKA-PETLA, 2026-08-08: strzałka = dowolna
     * następna jednostka, Spacja = następna AKTYWNA (z ruchem) jednostka).
     */
    function cyclablePlayerArmyLeadsBase(requireMoves: boolean): RuntimeUnit[] {
      const playerUnits = units.filter(
        u => u.ownerId === 0 && isUnitActiveForCycle(u) && (!requireMoves || stackCanMove(u)),
      );
      // BB2 (Evaluator runda 5, B-R5-1): grupowanie MUSI iść po stackRenderKey
      // (tożsamość STOSU + POZYCJA + garnizon), nie po gołym stackGroupIdOf ani
      // po gołym heksie — dwie jednostki tej samej, jawnie scalonej grupy mogą
      // realnie stać na RÓŻNYCH heksach (np. zwiadowca odjeżdżający sam z grupy
      // przez auto-explore), a gołe stackGroupIdOf zlewałoby je w JEDEN lead
      // obejmujący dwa heksy naraz — Spacja/strzałki HUD ◀▶ nigdy nie dotarłyby
      // do drugiego heksu. Ten sam klucz co armyMerge.ts:computeStackDisplay.
      const stacks = new Map<string, RuntimeUnit[]>();
      for (const u of playerUnits) {
        const key = stackRenderKey(u);
        const arr = stacks.get(key);
        if (arr) arr.push(u);
        else stacks.set(key, [u]);
      }
      const out: RuntimeUnit[] = [];
      for (const group of stacks.values()) {
        out.push(group[0]!);
      }
      out.sort((a, b) => {
        const sa = a.q + a.r;
        const sb = b.q + b.r;
        if (sa !== sb) return sa - sb;
        if (a.q !== b.q) return a.q - b.q;
        return a.r - b.r;
      });
      return out;
    }

    /** Wszystkie armie gracza (1 wiodąca/heks) z DOSTĘPNYM RUCHEM — kolejność przestrzenna.
     * Używane przez Spację i auto-cykl „bęben” po wyczerpaniu ruchu. */
    function cyclablePlayerArmyLeads(): RuntimeUnit[] {
      return cyclablePlayerArmyLeadsBase(true);
    }

    /** Wszystkie armie gracza (1 wiodąca/heks), NIEZALEŻNIE od dostępnego ruchu — kolejność
     * przestrzenna. Używane przez strzałki HUD ◀▶ (decyzja właściciela 2026-08-08). */
    function cyclablePlayerArmyLeadsAll(): RuntimeUnit[] {
      return cyclablePlayerArmyLeadsBase(false);
    }

    /** BB2 (Evaluator runda 5, B-R5-1): klucz dopasowania w cycleToAdjacentPlayerUnit — MUSI być
     *  spójny z cyclablePlayerArmyLeadsBase (ten sam stackRenderKey), inaczej fallback po
     *  zniknięciu `afterId` z listy trafiłby na niewłaściwą (np. rezydenta na innym heksie) armię. */
    function armyLeadHexKey(u: RuntimeUnit): string {
      return stackRenderKey(u);
    }

    /**
     * Spacja i auto-cykl „bęben” po ruchu — cykl WYŁĄCZNIE po armiach gracza, które jeszcze mają
     * dostępny ruch w tej turze. Strzałki HUD ◀▶ wołają tę samą funkcję z `opts.all=true`, co
     * przełącza na `cyclablePlayerArmyLeadsAll()` (wszystkie armie, niezależnie od ruchu) —
     * decyzja właściciela R-SPACJA-KOLEJNA-JEDNOSTKA-PETLA (2026-08-08).
     */
    function cycleToAdjacentPlayerUnit(
      afterId: string | null,
      delta: 1 | -1,
      opts?: { all?: boolean },
    ): void {
      if (!isWorldMapUnitMode()) return;
      const list = opts?.all === true ? cyclablePlayerArmyLeadsAll() : cyclablePlayerArmyLeads();
      if (list.length === 0) {
        clearPlayerUnitSelection();
        return;
      }
      // Domyślnie (brak zaznaczenia LUB zaznaczona jednostka nie występuje już w `list` — np.
      // bęben po ruchu, kiedy jednostka właśnie wyczerpała ruch i wypadła z listy „z ruchem"):
      // start tuż PRZED pierwszym/PO ostatnim elemencie, żeby +delta wylądował na list[0]
      // (w przód) albo list[list.length-1] (wstecz) — bez pomijania najbliższej możliwej
      // jednostki w kierunku ruchu.
      let cur = delta > 0 ? -1 : 0;
      if (afterId !== null) {
        const idxById = list.findIndex(u => u.id === afterId);
        if (idxById >= 0) {
          cur = idxById;
        } else {
          const selected = units.find(x => x.id === afterId);
          if (selected) {
            const key = armyLeadHexKey(selected);
            const idxByHex = list.findIndex(u => armyLeadHexKey(u) === key);
            if (idxByHex >= 0) cur = idxByHex;
          }
        }
      }
      const idx = (cur + delta + list.length) % list.length;
      const next = list[idx]!;
      selectPlayerUnit(next.id);
      focusCameraOnUnit(next);
    }

    /** Rozwiązanie jednostki gracza — usuwa z mapy, zwraca Manpower do puli imperium. */
    function disbandPlayerUnit(unitId: string): boolean {
      const idx = units.findIndex(x => x.id === unitId);
      if (idx < 0) return false;
      const u = units[idx]!;
      if (u.ownerId !== 0) return false;

      const ep = empireEpochForOwner(0);
      const mpMults = civManpowerMultsForOwner(0);
      const mpRefund = unitManpowerCostForType(u.typeId, ep, mpMults.maxMult);
      refundManpowerToEmpire(cities, 0, ep, mpRefund, mpMults.maxMult);

      const siegeCityId = u.oblegaCityId;
      const wasGarnizon = u.inGarnizon === true;
      const cityForGarnizon = cityAtUnit(u);

      units.splice(idx, 1);

      if (siegeCityId) {
        const stillMarked = units.some(x => x.oblegaCityId === siegeCityId);
        if (!stillMarked) {
          const sc = cities.find(c => c.id === siegeCityId);
          if (sc?.oblegane) {
            const bId = sc.oblegajacyOwnerId ?? siegeBesiegerByCity.get(siegeCityId);
            const adj = bId !== undefined && units.some(
              x => x.ownerId === bId && hexDistance(x.q, x.r, sc.q, sc.r) === 1,
            );
            if (!adj) endMapSiege(siegeCityId);
          }
        }
      }

      if (wasGarnizon && cityForGarnizon) syncGarnizonForCity(cityForGarnizon);

      if (selectedId === unitId) clearPlayerUnitSelection();
      forceVisibleUnitId = null;
      syncUnitsRender();
      refreshFog();
      refreshSiegeMarkers();

      const cityLabel = cityAtUnit(u)?.name ?? cities.find(c => c.ownerId === 0)?.name ?? 'imperium';
      showHintMessage(
        u.typeId + ' rozwiązany — +' + formatManpower(mpRefund) + ' rekrutów → pula imperium (' + cityLabel + ')',
        4000,
      );
      refreshD1bHud();
      return true;
    }

    // -------------------------------------------------------------------
    // Mechanizm "Zastąp" (ZASTAP-JEDNOSTKI-PLAN.md) — decyzje UX wdrożone:
    //   koszt = max(0, koszt_nowej - koszt_starej) w Pieniądzu (dopłata; sidegrade/
    //     downgrade = 0, bez zwrotu);
    //   tura = zużywa ruch (ruchLeft = 0 po zamianie);
    //   zasięg = CAŁE terytorium gracza (decyzja właściciela, zmiana zakresu 2026-07-19) —
    //     dowolny heks należący do gracza (isPlayerTerritoryHex), NIE tylko garnizon miasta;
    //     gdy jednostka stoi w mieście, bramka koszary/braz-access nadal per to miasto,
    //     poza miastem — "OR po wszystkich miastach gracza" (replaceAvailabilityCtxEmpireWide);
    //   HP = zachowany % (newHp = round(newMaxHp * oldHp/oldMaxHp), min 1);
    //   limit = raz na turę na jednostkę (RuntimeUnit.replaceUsedThisTurn, reset w N: End turn);
    //   nacja = tylko własna (unitAllowedForCivNation w availableReplacementsFor, niezmienione);
    //   zakres = JEDNA zaznaczona karta w stosie (selectedId), nie cały stos;
    //   ludność = POMINIĘTA (decyzja właściciela 2026-07-19: "Zastąp" kosztuje WYŁĄCZNIE
    //     Pieniądz — wszystkie 73 jednostki w units.json mają dziś "Ludność"=1, więc
    //     różnicowanie kosztów ludności i tak nic by nie dało; rozliczenie wycofane);
    //   manpower = POMINIĘTE — unitManpowerCost() zależy wyłącznie od epoki imperium, nie
    //     od typu jednostki, więc nie ma tu roli do odegrania w obecnym modelu danych.
    // -------------------------------------------------------------------

    /** Miasto-garnizon jednostki, o ile stoi na heksie WŁASNEGO miasta (cityAtUnit już filtruje ownerId). */
    function unitReplaceGarrisonCity(u: RuntimeUnit): City | undefined {
      return cityAtUnit(u);
    }

    /** Czy jednostka stoi na heksie należącym do terytorium gracza (miasto/posterunek/fort) —
     *  zasięg akcji "Zastąp" (decyzja właściciela: całe terytorium, nie tylko garnizon miasta).
     *  Reużywa dokładnie ten sam mechanizm co bramka trybu budowy (main.ts handleHexClick). */
    function isUnitInPlayerTerritory(u: RuntimeUnit): boolean {
      const nodes = buildAllTerritoryNodes();
      return isPlayerTerritoryHex(u.q, u.r, playerCityNodes(), nodes, 0);
    }

    /** Kontekst dostępności dla availableReplacementsFor — jak productionCtxForCity (cityPanel.ts),
     *  per-miasto garnizonu (bramka koszary/braz-access per to miasto, gdy jednostka w nim stoi).
     *  Cienki wrapper nad buildReplaceAvailabilityCtx (game/unit-replace-context.ts) — zbiera
     *  dane zamknięte nad main.ts, samo składanie AvailabilityContext (w tym wymagane pole
     *  empireResourceStock, UNIT-REPLACE-EVOCATI-Q1) żyje w testowalnej, pure funkcji. */
    function replaceAvailabilityCtxForCity(city: City): AvailabilityContext {
      const ownImprovements = placedImprovementsForOwner(city.ownerId);
      return buildReplaceAvailabilityCtx({
        epoch: empireEpochForOwner(city.ownerId),
        builtBuildingIds: cityBuilt.get(city.id) ?? [],
        civBonusy: civBonusyForOwnerId(city.ownerId),
        civUnitNacja: unitNacjaForCivKey(civKeyForOwnerId(city.ownerId)),
        // Temat #4: grant "z trasy" dolicza się AND-owo (braz syntetycznie,
        // zelazo OR-em) — patrz placedImprovementsWithBrazTradeGrant/
        // hasKopalniaNaZlozuZelazaOrTradeGrant.
        placedImprovements: placedImprovementsWithTradeGrants(city.ownerId, ownImprovements),
        hasKopalniaNaZlozuZelaza: hasKopalniaNaZlozuZelazaOrTradeGrant(city.ownerId, ownImprovements),
        empireResourceStock: citySurowceSumForOwner(city.ownerId),
        // audyt #11: "Zastąp" nie może dać drugiej żywej Super-jednostka -- ta sama
        // bramka co productionCtxForCity (cityPanel.ts).
        aliveUnitTypeNames: new Set(units.filter(x => x.ownerId === city.ownerId).map(x => x.typeId)),
        kosztJednostekPace: player.kosztJednostekPace ?? 'niski',
        ownerId: city.ownerId,
        difficulty: _menuDifficulty,
        // R-BUDYNEK-PORTOWY-MIASTA-NADBRZEZNE (Maciej 2026-08-09): bramka Naval dla
        // "Zastąp" w garnizonie — per TO miasto (tak jak koszary/braz-access wyżej).
        cityHasCoastOrRiver: cityHasCoastOrRiverAccess(city),
      });
    }

    /** Kontekst dostępności dla availableReplacementsFor, gdy jednostka stoi w POLU (w granicach
     *  terytorium, bez miasta pod nią) — bramka koszary/braz-access "OR po wszystkich miastach
     *  gracza" (decyzja właściciela: Zastąp działa w całym terytorium, nie tylko w garnizonie;
     *  unia builtBuildingIds ze wszystkich miast gracza -> built.has('koszary') /
     *  cityHasPiecHutniczy() zwraca true, gdy KTÓREKOLWIEK miasto spełnia warunek).
     *  Cienki wrapper nad buildReplaceAvailabilityCtx — patrz replaceAvailabilityCtxForCity. */
    function replaceAvailabilityCtxEmpireWide(): AvailabilityContext {
      const builtUnion = new Set<string>();
      for (const c of cities) {
        if (c.ownerId !== 0) continue;
        for (const id of cityBuilt.get(c.id) ?? []) builtUnion.add(id);
      }
      const ownImprovements = placedImprovementsForOwner(0);
      return buildReplaceAvailabilityCtx({
        epoch: empireEpochForOwner(0),
        builtBuildingIds: Array.from(builtUnion),
        civBonusy: civBonusyForOwnerId(0),
        civUnitNacja: unitNacjaForCivKey(civKeyForOwnerId(0)),
        placedImprovements: placedImprovementsWithTradeGrants(0, ownImprovements),
        hasKopalniaNaZlozuZelaza: hasKopalniaNaZlozuZelazaOrTradeGrant(0, ownImprovements),
        // ta funkcja jest empire-wide wyłącznie dla gracza (ownerId 0, patrz literały
        // wyżej w tej samej funkcji), więc suma surowców też liczona dla ownerId 0.
        empireResourceStock: citySurowceSumForOwner(0),
        // audyt #11: jak wyżej (replaceAvailabilityCtxForCity) — całe terytorium gracza.
        aliveUnitTypeNames: new Set(units.filter(x => x.ownerId === 0).map(x => x.typeId)),
        kosztJednostekPace: player.kosztJednostekPace ?? 'niski',
        ownerId: 0,
        difficulty: _menuDifficulty,
        // R-BUDYNEK-PORTOWY-MIASTA-NADBRZEZNE (Maciej 2026-08-09): bramka Naval "OR po
        // wszystkich miastach gracza" — jednostka w polu (bez konkretnego garnizonu) może
        // zastąpić się jednostką morską, gdy KTÓREKOLWIEK miasto gracza ma dostęp do wody
        // (ten sam wzorzec unii co builtBuildingIds wyżej).
        cityHasCoastOrRiver: cities.some(c => c.ownerId === 0 && cityHasCoastOrRiverAccess(c)),
      });
    }

    /** Lista zamienników dostępnych TERAZ dla jednostki `u` (pusta gdy poza terytorium gracza).
     *  W garnizonie miasta -> bramka per to miasto; w polu (w granicach terytorium, bez miasta
     *  pod jednostką) -> bramka "OR po wszystkich miastach gracza". */
    function computeUnitReplacements(u: RuntimeUnit): ProductionItem[] {
      if (!isUnitInPlayerTerritory(u)) return [];
      const city = unitReplaceGarrisonCity(u);
      const ctx = city ? replaceAvailabilityCtxForCity(city) : replaceAvailabilityCtxEmpireWide();
      return availableReplacementsFor(u.typeId, data, Array.from(player.zbadane), ctx);
    }

    /** Koszt rekrutacji Pieniądzem jednostki `typeId` (dla dopłaty = nowa - stara). */
    function replaceUnitMoneyCost(typeId: string): number {
      const item = unitProductionItem(
        typeId, data, civBonusyForOwnerId(0), player.kosztJednostekPace ?? 'niski', 0, _menuDifficulty,
      );
      return item?.koszt ?? 0;
    }

    /** Otwórz modal wyboru zamiennika dla jednostki `u` (akcja "Zastąp" w ArmyStackHud). */
    function openUnitReplacePicker(u: RuntimeUnit): void {
      if (u.ownerId !== 0) return;
      if (!isUnitInPlayerTerritory(u)) {
        showHintMessage('Zastąp: dostępne tylko na własnym terytorium.', 3000);
        return;
      }
      if (u.replaceUsedThisTurn) {
        showHintMessage('Zastąp: już wykorzystano w tej turze.', 2500);
        return;
      }
      const replacements = computeUnitReplacements(u);
      if (replacements.length === 0) {
        showHintMessage('Zastąp: brak dostępnych zamienników tego typu.', 2500);
        return;
      }
      const oldCost = replaceUnitMoneyCost(u.typeId);
      showUnitReplacePicker({
        unitName: u.typeId,
        skarb: player.skarbiec,
        options: replacements.map(it => {
          const udef = lookupUnitDef(it.id);
          return {
            id: it.id,
            name: it.nazwa,
            icon: unitIconSvg(udef, it.id),
            surcharge: Math.max(0, it.koszt - oldCost),
            atk: unitAtak(udef),
            def: unitObrona(udef),
            hpMax: unitHealth(udef),
          };
        }),
        onPick: (newTypeId) => performUnitReplace(u.id, newTypeId),
      });
    }

    /** Wykonaj zamianę jednostki `unitId` na `newTypeId` (runtime, po wyborze w modalu). */
    function performUnitReplace(unitId: string, newTypeId: string): void {
      const u = units.find(x => x.id === unitId);
      if (!u || u.ownerId !== 0) return;
      if (!isUnitInPlayerTerritory(u)) return;
      if (u.replaceUsedThisTurn) return;
      const newDef = lookupUnitDef(newTypeId);
      if (!newDef) return;

      const surcharge = Math.max(0, replaceUnitMoneyCost(newTypeId) - replaceUnitMoneyCost(u.typeId));
      if (player.skarbiec < surcharge) {
        showHintMessage('Zastąp: brak Pieniądza na dopłatę (' + surcharge + ' 💰)', 3000);
        return;
      }

      const oldDef = lookupUnitDef(u.typeId);
      const oldMaxHp = unitHealth(oldDef);
      const newMaxHp = unitHealth(newDef);
      const oldHp = u.hp ?? oldMaxHp;
      const newHp = Math.max(1, Math.round(newMaxHp * (oldMaxHp > 0 ? oldHp / oldMaxHp : 1)));

      player.skarbiec -= surcharge;

      const oldTypeId = u.typeId;
      const isSuper = newDef['Super-jednostka'] === 'TAK';
      u.typeId = newTypeId;
      u.category = categoryOf(newTypeId, newDef['Rola (linia)'] ?? '', isSuper, newDef['Typ']);
      u.hp = newHp;
      u.ruchLeft = 0;
      u.replaceUsedThisTurn = true;

      syncUnitsRender();
      refreshFog();
      refreshD1bHud();

      // Etykieta miasta w toaście: garnizon jednostki, a poza miastem (całe terytorium
      // gracza) — pierwsze miasto gracza jako fallback (ten sam wzorzec co disbandPlayerUnit).
      const replaceCity = unitReplaceGarrisonCity(u) ?? cities.find(c => c.ownerId === 0);
      showHintMessage(
        oldTypeId + ' → ' + newTypeId
          + (surcharge > 0 ? ' (dopłata ' + surcharge + ' 💰)' : ' (bez dopłaty)')
          + (replaceCity ? (' — ' + replaceCity.name) : ''),
        3500,
      );
    }

    function buildPlayerCityListEntries(): CityListEntry[] {
      return cities
        .filter(c => c.ownerId === 0)
        .map(c => {
          const prod = cityProd.get(c.id);
          const front = prod ? frontItem(prod) : null;
          const productionLine = front
            ? `${front.nazwa} • ${prod?.postep ?? 0}/${front.koszt} 🔨`
            : cityHasActionableProduction(c)
              ? 'Kolejka pusta'
              : undefined;
          const gar = c.garnizon ?? 0;
          return {
            id: c.id,
            name: c.name,
            population: c.population,
            productionLine,
            metaLine: gar > 0 ? `Garnizon: ${gar}` : undefined,
          };
        });
    }

    function buildPlayerArmyListEntries(): ArmyListEntry[] {
      const playerUnits = units.filter(u => u.ownerId === 0);
      const stacks = new Map<string, typeof playerUnits>();
      for (const u of playerUnits) {
        // C-GARN-Q1: ufortyfikowane jednostki grupuj po heksie miasta (jak armia),
        // żeby lista armii nie rozdzielała stosu po wejściu do garnizonu.
        // BB2 (Evaluator runda 5, B-R5-1): ta lista miała WŁASNE, niezależne
        // grupowanie „po heksie", które omijało activeUnitStack/visibleStackOnHex —
        // dwie armie o różnym stackGroupId na wspólnym origin pokazywały się tu
        // jako JEDEN wpis o zsumowanym/błędnym ruchu. `stackRenderKey` (tożsamość
        // stosu + pozycja + garnizon, ten sam klucz co armyMerge.ts:
        // computeStackDisplay) naprawia to bez zmiany zachowania dla jednostek bez
        // jawnego stackGroupId (fallback koduje ownerId+heks+garnizon identycznie
        // jak dawny gołoheksowy klucz).
        const key = stackRenderKey(u);
        const arr = stacks.get(key);
        if (arr) arr.push(u);
        else stacks.set(key, [u]);
      }
      const out: ArmyListEntry[] = [];
      for (const group of stacks.values()) {
        const lead = group[0]!;
        const inGarnizon = group.some(u => u.inGarnizon === true);
        const ufortyfikowanyWPolu = group.some(u => u.ufortyfikowanyWPolu === true);
        const sentry = group.some(u => u.sentry === true);
        const autoExplore = group.some(u => u.autoExplore === true);
        const types = [...new Set(group.map(u => u.typeId))];
        const name = group.length === 1
          ? lead.typeId
          : types.length === 1
            ? `${types[0]!} ×${group.length}`
            : formatArmiaLabel(group.length);
        const ruchLeft = planningStackRuchLeft(group);
        const ruchMax = Math.max(...group.map(u => u.ruch));
        // Suma HP stosu: armia = stos, więc pokazujemy łączny stan zdrowia
        // (np. 34/50), a nie zdrowie pojedynczej jednostki wiodącej.
        let hp = 0;
        let hpMax = 0;
        for (const u of group) {
          const udef = unitDefFor(u);
          const unitMaxHp = unitHealth(udef);
          hp += u.hp ?? unitMaxHp;
          hpMax += unitMaxHp;
        }
        // Liczby ruchu pokazuje teraz pasek „Ruch X/Y” (armyListHud.ts, al-bar-lbl) —
        // detailLine zostaje wyłącznie znacznikiem stosu i ostrzeżeniem o wyczerpanym ruchu.
        const detailParts: string[] = [];
        if (group.length > 1) detailParts.push('armia');
        if (ruchLeft === 0) detailParts.push('Ruch wykorzystany w tej turze');
        out.push({
          id: lead.id,
          name,
          unitCount: group.length,
          hexLabel: `(${lead.q}, ${lead.r})`,
          detailLine: detailParts.length > 0 ? detailParts.join(' · ') : undefined,
          metaLine: types.length > 1 ? types.join(', ') : undefined,
          ruchLeft,
          ruchMax,
          hp,
          hpMax,
          inGarnizon,
          ufortyfikowanyWPolu,
          sentry,
          autoExplore,
        });
      }
      out.sort((a, b) => a.name.localeCompare(b.name, 'pl'));
      return out;
    }

    /**
     * Lista dyplomacji (panel + toolbar) — wszystkie ODKRYTE w mgle cywilizacje.
     * Kontakt formalny = automatyczny przy pierwszym odkryciu (karta informacyjna).
     */
    function isActiveDiploOwner(ownerId: number): boolean {
      if (ownerId === 0 || isBarbarian(ownerId) || eliminatedOwners.has(ownerId)) return false;
      if (aiOwnerCivMap.has(ownerId)) return true;
      return cities.some(c => c.ownerId === ownerId) || units.some(u => u.ownerId === ownerId);
    }

    /** AI-MANAGE-Q1=A: major AI = ownerId > 0, nie barbarzyńca, nie państwo-miasto/defensiveCopy. */
    function isCityStateOwner(ownerId: number): boolean {
      return simplifiedDiplomacyOwners.has(ownerId) || typCityCopyOwners.has(ownerId);
    }

    function buildPlayerDiploRelations(): DiploRelation[] {
      const rels: DiploRelation[] = [];
      const contacted = getDiplomaticContacts();
      for (const otherId of contacted) {
        if (!isActiveDiploOwner(otherId)) continue;
        const rel = getDiploRelation(0, otherId);
        const layer = diplomacyLayerForOwner(
          otherId,
          simplifiedDiplomacyOwners,
          foreignTypeOwners,
          contacted,
        );
        rels.push({
          ownerId: otherId,
          civ: ownerDiploLabel(otherId),
          isCityState: isOwnerClusterCityState(otherId, ownerCityStateOpts()),
          ikonaId: civTypeForOwner(otherId),
          kolorHex: civKolorHexFn(otherId),
          layer,
          tier: relationTier(rel),
          zaufanie: Math.round(Math.max(0, Math.min(100, rel.zaufanie ?? 0))),
          // R-MOC-HUD-GLOWNY-Q1=C: lista dyplomacji (karta per-cywilizacja) -> respekt
          // EFEKTYWNY, dla spójności z ekranem audiencji (otwieranym z tej samej listy),
          // który liczy respekt tym samym wariantem — patrz audienceRelTotalEffective.
          respekt: objectiveRespektPctTowardEffective(otherId),
          theirRespekt: computeRespekt(
            objectivePowerForOwnerEffective(otherId),
            objectivePowerForOwnerEffective(0),
          ),
          population: cities.filter(c => c.ownerId === otherId).reduce((s, c) => s + c.population, 0),
          armyCount: units.filter(u => u.ownerId === otherId).length,
          cultureLabel: civCultureLabelForKey(civKeyForOwner(otherId)),
          epochLabel: epochLabelForOwner(otherId),
          contactEstablished: diplomaticContactEstablished.has(otherId),
          activeTreaties: activeTreatyLabelsForPair(activeDeals, 0, otherId),
          wiarygodnosc: getWiarygodnosc(otherId),
        });
      }
      rels.sort((x, y) => x.civ.localeCompare(y.civ, 'pl'));
      return rels;
    }

    function buildPlayerDiploListEntries(): DiploListEntry[] {
      return buildPlayerDiploRelations()
        .map(diploListEntryFromRelation)
        .filter((e): e is DiploListEntry => e !== null);
    }

    /**
     * R-DYPLOMACJA-LISTA-I-PODGLAD-PRZED-WIZYTA (Maciej 2026-08-09) — dane pop-upu
     * podsumowania pary dyplomatycznej dla `ownerId` (cywilizacja kliknięta na liście),
     * pokazywanego PRZED pełną audiencją.
     *
     * B2 (Evaluator runda 1, mgła wojny): `isVisiblePartner` odcina partnerów wojny/
     * sojuszu/handlu, których gracz NIGDY nie spotkał lub którzy zostali wyeliminowani —
     * ten sam warunek widoczności co istniejące kolektory `collectWarsWithPlayer`/
     * `collectKnownWarsBetweenOthers` (`isActiveDiploOwner` + `getDiplomaticContacts()`),
     * z JEDNYM świadomym wyjątkiem: gracz (id===0) jest zawsze widoczny — patrz komentarz
     * przy `DiploPairSummaryPartner.isPlayer` w `ui/diplomacyPanel.ts` (decyzja B2).
     */
    function buildDiploPairSummaryData(ownerId: number): DiploPairSummaryData | null {
      if (!isActiveDiploOwner(ownerId)) return null;
      const isVisiblePartner = (id: number): boolean =>
        id === 0 || (isActiveDiploOwner(id) && getDiplomaticContacts().has(id));
      const toPartner = (id: number): DiploPairSummaryPartner => ({
        ownerId: id,
        name: ownerDiploLabel(id),
        isPlayer: id === 0,
      });
      const wars = warPartnerIdsForOwner(diplomacyRelations, ownerId, isVisiblePartner).map(toPartner);
      const alliances = dealPartnerIdsForOwner(activeDeals, ownerId, 'sojusz', isVisiblePartner).map(toPartner);
      const deals = dealPartnerIdsForOwner(activeDeals, ownerId, 'handel', isVisiblePartner).map(toPartner);
      const rel = getDiploRelation(0, ownerId);
      return {
        ownerId,
        civName: ownerDiploLabel(ownerId),
        ikonaId: civTypeForOwner(ownerId),
        kolorHex: civKolorHexFn(ownerId),
        tier: relationTier(rel),
        wars,
        alliances,
        deals,
      };
    }

    function buildPlayerDiploSummary(): DiploPlayerSummary {
      const civKey = civKeyForOwner(0);
      const playerCities = cities.filter(c => c.ownerId === 0);
      const lines = formatDiploPlayerSummaryLines({
        // R-MOC-HUD-GLOWNY-Q1=C: podsumowanie gracza na liście dyplomacji ("Moc: X",
        // "Ranking mocy: Y. z Z") -> EFEKTYWNA, jak reszta warstwy UI Mocy.
        militaryPower: objectivePowerForOwnerEffective(0),
        powerRank: buildAbsolutePowerRankEffective(),
        wiarygodnosc: getWiarygodnosc(0),
        population: playerCities.reduce((s, c) => s + c.population, 0),
        armyCount: units.filter(u => u.ownerId === 0).length,
      });
      return {
        name: ownerDiploLabel(0),
        ikonaId: civTypeForOwner(0),
        kolorHex: civKolorHexFn(0),
        cultureLabel: civCultureLabelForKey(civKey),
        epochLabel: epochLabelForOwner(0),
        era: empireEpochForOwner(0),
        personalityTags: diplomacyPersonalityTags(civKey),
        detailLine: lines.detailLine,
        metaLine: lines.metaLine,
      };
    }

